head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf05100";
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — resultList, sys_start_dd, sys_end_dd

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "span_46", attr: "__html", fn: function () { return ([String(dma_page.get("total")), String(dma_page.get("currentPage")), String(dma_page.get("pageCount"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("총 <strong style=\"color:#666666\">" + String(dma_page.get("total")) + "</strong>건 <span>(" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + ")</span>") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_resultList", fn: function(){ return (!(String(((dma_pageContext.get("resultList") ?? "")) == null ? '' : ((dma_pageContext.get("resultList") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_paramSearchWord", fn: function () { return String((dma_pageContext.get("searchWord") ?? "")); } },
        { childId: "ipt_searchWord", fn: function () { return String((dma_pageContext.get("searchWord") ?? "")); } },
        { childId: "cal_startDate", fn: function () { return String((dma_pageContext.get("startDate") ?? "")); } },
        { childId: "cal_endDate", fn: function () { return String((dma_pageContext.get("endDate") ?? "")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_datefmt_cal_startDate
 * @description 초기화 — datefmt cal start Date
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_startDate = function () { $c.date.checkCalendarFormat("cal_startDate", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_endDate
 * @description 초기화 — datefmt cal end Date
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_endDate = function () { $c.date.checkCalendarFormat("cal_endDate", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        let startDate = $c.util.getComponent('cal_startDate').getValue(); if (startDate == null) { startDate = ''; }
        let endDate = $c.util.getComponent('cal_endDate').getValue(); if (endDate == null) { endDate = ''; }
        if (startDate === "" && endDate === "") {
            const sys_start_dd = (String(((dma_pageContext.get("sys_start_dd") ?? "")) == null ? '' : ((dma_pageContext.get("sys_start_dd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("sys_start_dd") ?? "")) == null ? '' : ((dma_pageContext.get("sys_start_dd") ?? ""))));
            const sys_end_dd = (String(((dma_pageContext.get("sys_end_dd") ?? "")) == null ? '' : ((dma_pageContext.get("sys_end_dd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("sys_end_dd") ?? "")) == null ? '' : ((dma_pageContext.get("sys_end_dd") ?? ""))));
            $c.util.getComponent('cal_startDate').setValue(sys_start_dd);
            $c.util.getComponent('cal_endDate').setValue(sys_end_dd);
        }
        const pageIndex = $c.util.getComponent('ipt_currentPage').getValue();
        const pageObj = $('.paging td:contains(' + pageIndex + ')');
        const pagingLeng = $('.paging td:contains(' + pageIndex + ')').length;
        for (let i = 0; i < pagingLeng; i++) {
            const obj = pageObj[i];
            const val = $(obj).text();
            if (pageIndex !== val) {
                continue;
            }
            const font = "<font color='blue'>" + val + "</font>";
            $(obj).html(font);
            $(obj).attr("style", "font-size:15px;");
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05100.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 키 corplist#corpnewreqlist 를 쓰는 tx 가 2개다(tx_fn_search, tx_fn_goPage)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":1
        ,"mmenu":1
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf05100' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_datefmt_cal_startDate();
        scwin.init_datefmt_cal_endDate();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf05100.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_searchWord_onkeydown
 * @description ipt_searchWord 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_searchWord_onkeydown = async function(e){
    try {
        const ev = e;
        const event = ev;
        if(event.KeyCode===13) await scwin.search();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf05100.ipt_searchWord_onkeydown' }); }
};

/**
 * @method
 * @name ipt_searchWord_onkeyup
 * @description ipt_searchWord 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_searchWord_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        fn_boardCheck(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05100.ipt_searchWord_onkeyup' }); }
};

/**
 * @method
 * @name btn_search_onclick
 * @description btn_search 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf05100.btn_search_onclick' }); }
};

/**
 * @method
 * @name grd_resultList_oncellclick
 * @description grd_resultList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_resultList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_resultList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.corpMasterView(r["isurCd"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_resultList.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_search
 * @description search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_search = async function () {
    const sbmOptions = {
        id: "tx_fn_search",
        method: "post",
        action: "/corp/corpList.do?method=corpNewReqList",
        ref: "dma_searchReq",
        target: "dlt_resultList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goPage
 * @description go Page 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goPage = async function () {
    const sbmOptions = {
        id: "tx_fn_goPage",
        method: "post",
        action: "/corp/corpList.do?method=corpNewReqList",
        ref: "dma_goPageReq",
        target: "dlt_resultList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkDate
 * @description check Date 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkDate = async function () {
    const frm = (document.JLDINF05100 || { elements: [] });
    let startDate = $c.util.getComponent('cal_startDate').getValue(); if (startDate == null) { startDate = ''; }
    let endDate = $c.util.getComponent('cal_endDate').getValue(); if (endDate == null) { endDate = ''; }
    if (startDate === "" || endDate === "") {
        return;
    }
    if (startDate > endDate) {
        await $c.win.alert("종료일은 시작일 이후 날짜로 입력하세요");
        $c.util.getComponent("dma_searchReq").set("endDate", "");
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    if ($c.str.getByteLength($c.util.getComponent('ipt_searchWord').getValue()) === 0) {
        await $c.win.alert("발행기관명 또는 발행기관코드를 입력하세요\n");
        $c.util.getComponent("ipt_searchWord").focus();
        return;
    }
    const frm = (document.JLDINF05100 || { elements: [] });
    if ($c.util.getComponent('cal_startDate').getValue()> $c.util.getComponent('cal_endDate').getValue()) {
        await $c.win.alert("검색 종료일이 시작일보다 이전날짜입니다.\n");
        ($c.util.getComponent('cal_endDate') && $c.util.getComponent('cal_endDate').setFocus ? $c.util.getComponent('cal_endDate').setFocus() : ($c.util.getComponent('cal_endDate') && $c.util.getComponent('cal_endDate').focus ? $c.util.getComponent('cal_endDate').focus() : console.warn('[sdd] focus 대상 미해결: cal_endDate')));
        return;
    }
    frm.action = "/corp/corpList.do?method=corpNewReqList";
    await scwin.tx_fn_search();
};

/**
 * @method
 * @name goPage
 * @description go Page 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goPage = async function () {
    if (($c.util.getComponent('ipt_searchWord').getValue() == null ? '' : String($c.util.getComponent('ipt_searchWord').getValue())) === '') {
        $c.util.getComponent('ipt_searchWord').setValue($("paramSearchWord").val());
    }
    const frm = (document.JLDINF05100 || { elements: [] });
    if ($c.util.getComponent('cal_startDate').getValue()> $c.util.getComponent('cal_endDate').getValue()) {
        await $c.win.alert("검색 종료일이 시작일보다 이전날짜입니다.\n");
        ($c.util.getComponent('cal_endDate') && $c.util.getComponent('cal_endDate').setFocus ? $c.util.getComponent('cal_endDate').setFocus() : ($c.util.getComponent('cal_endDate') && $c.util.getComponent('cal_endDate').focus ? $c.util.getComponent('cal_endDate').focus() : console.warn('[sdd] focus 대상 미해결: cal_endDate')));
        return;
    }
    frm.action = "/corp/corpList.do?method=corpNewReqList";
    await scwin.tx_fn_goPage();
};

/**
 * @method
 * @name corpMasterView
 * @description corp Master View 처리
 * @param {*} cd cd
 * @returns {void}
 * @hidden N
 */
scwin.corpMasterView = function (cd) {
    const formName = (document.popupForm || { elements: [] });
    $c.util.getComponent("dma_searchReq").set("isurCd", cd);
    fn_popupCorpView(formName, cd);
};

/**
 * @method
 * @name Chk_Date
 * @description Chk Date 처리
 * @param {*} Name Name
 * @param {String} Date_Str Date_Str
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.Chk_Date = async function (Name, Date_Str) {
    let sdate = Name.getValue(); if (sdate == null) { sdate = ''; }
    pyear = sdate.substr(0, 4);
    pmonth = sdate.substr(4, 2);
    pday = sdate.substr(6, 2);
    src = pyear + '-' + pmonth + '-' + pday;
    syear = parseInt(pyear, 10);
    smonth = parseInt(pmonth, 10) - 1;
    sday = parseInt(pday, 10);
    sodate = new Date(Date.UTC(syear, smonth, sday));
    soyear = (sodate.getYear() < 2000) ? sodate.getYear() + 1900 : sodate.getYear();
    somonth = sodate.getMonth();
    soday = sodate.getDate();
    if (sdate !== "" && (syear !== soyear || smonth !== somonth || sday !== soday)) {
        await $c.win.alert("입력한 " + Date_Str + "이 올바르지 않습니다. \n");
        Name.focus();
        return false;
    }
    if (sdate !== "" && sdate.length !== 8) {
        await $c.win.alert("입력한 " + Date_Str + "이 8자리가 아닙니다. \n");
        Name.focus();
        return false;
    }
    if (sdate === "") {
        Name.setValue('');
    } else {
        Name.setValue(sdate);
    }
    return true;
};

/**
 * @method
 * @name krxpage_pagenavigator_90_onclick
 * @description krxpage_pagenavigator_90 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_90_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_searchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_90.page' }); } await scwin.goPage(); };
